quick-entry.snippet:
struct QuickEntryLabel: View {
    let title: String
    let detail: String
    let symbol: String
    var menu = false
    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: symbol).font(.system(size: 18, weight: .regular))
                .foregroundStyle(QingYouStyle.accent).frame(width: 24)
            VStack(alignment: .leading, spacing: 5) {
                Text(title).font(.system(size: 13, weight: .medium)).foregroundStyle(.primary)
                Text(detail).font(.system(size: 11)).foregroundStyle(.secondary)
            }
            Spacer(minLength: 8)
            Image(systemName: menu ? "chevron.down" : "chevron.right")
                .font(.system(size: 10, weight: .medium)).foregroundStyle(.secondary)
        }.padding(16).frame(maxWidth: .infinity, minHeight: 72, alignment: .leading)
            .contentShape(RoundedRectangle(cornerRadius: QingYouStyle.radius))
    }
}

tool-tile.snippet:
struct ToolTile: View {
    let command: ToolCommand
    let enabled: Bool
    let staged: Bool
    let action: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 10) {
                Image(systemName: command.symbol).font(.system(size: 17, weight: .regular))
                    .foregroundStyle(enabled ? QingYouStyle.accent : Color.secondary)
                    .frame(width: 22)
                Text(command.title).font(.system(size: 13, weight: .semibold))
                Spacer(minLength: 0)
                if staged && enabled {
                    Image(systemName: "checkmark.circle.fill")
                        .foregroundStyle(QingYouStyle.success).font(.system(size: 12))
                        .accessibilityLabel("适用于已选文件")
                }
            }
            Text(command.detail).font(.system(size: 12)).foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, minHeight: 36, alignment: .topLeading)
                .fixedSize(horizontal: false, vertical: true)
            HStack {
                Button(staged ? "运行工具" : "选择文件…", action: action)
                    .buttonStyle(SoftActionStyle())
                    .disabled(!enabled)
                    .help(enabled ? command.title : "当前选择的文件类型不适用")
                    .accessibilityLabel(command.title + (staged ? "，运行工具" : "，选择文件"))
                Spacer()
                if staged && !enabled {
                    Text("文件类型不适用").font(.system(size: 11)).foregroundStyle(.secondary)
                }
            }
        }
        .padding(18).frame(maxWidth: .infinity, alignment: .leading)
        .modifier(Surface()).modifier(HoverSurface(enabled: enabled))
    }
}

sidebarMaterial.snippet:
struct SidebarBackground: View {
    @Environment(\.accessibilityReduceTransparency) private var reduceTransparency
    var body: some View {
        ZStack {
            QingYouStyle.sidebar
            if !reduceTransparency { SidebarMaterial().opacity(0.75) }
        }
    }
}

private struct SidebarMaterial: NSViewRepresentable {
    func makeNSView(context: Context) -> NSVisualEffectView {
        let view = NSVisualEffectView()
        view.material = .sidebar
        view.blendingMode = .behindWindow
        view.state = .followsWindowActiveState
        return view
    }
    func updateNSView(_ view: NSVisualEffectView, context: Context) {}
}

hover.snippet:
struct HoverSurface: ViewModifier {
    var enabled = true
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var hovering = false
    func body(content: Content) -> some View {
        content
            .overlay(RoundedRectangle(cornerRadius: QingYouStyle.radius)
                .strokeBorder(hovering && enabled ? Color.primary.opacity(0.22) : .clear, lineWidth: 1)
                .allowsHitTesting(false))
            .onHover { hovering = $0 }
            .animation(reduceMotion ? nil : .easeOut(duration: 0.12), value: hovering)
    }
}

